package game.sanguo.mobile;
import game.sanguo.core.*;import java.util.*;
public class R02Occlusion {public static void main(String[] a)throws Exception {World w=new World(30,30);for(int q=0;q<30;q++)for(int r=0;r<30;r++)w.terrain[q][r]=World.Terrain.PLAIN;MapSceneSnapshot.Ground g=new MapSceneSnapshot.Ground(w);Hex peak=new Hex(15,15);TerrainSurface s=new TerrainSurface(g,Map.of(peak,2.6f));SceneCamera c=new SceneCamera();c.width=1080;c.height=1920;c.span=3;c.tilt=40;c.x=g.grid.x(peak);c.z=g.grid.z(peak);int occluded=0;for(float dx=-1;dx<1;dx+=.05f)for(float dz=-1;dz<1;dz+=.05f){float x=c.x+dx,z=c.z+dz,y=s.meshHeight(x,z),hit=s.rayHeight(c,c.screenX(x,z),c.screenY(x,z,y));if(hit>y+.02f)occluded++;}System.out.println("peak="+peak+" occluded="+occluded);if(occluded==0)throw new AssertionError();}}
